// Home.jsx
import React from "react";
import "./Home.css";

function Home() {
  return (
    <section className="home-section">
      <div className="home-card">
        <h1 className="home-title">Hola ¡Bienvenido soy Stephanie!</h1>
        <p className="home-subtitle">
          Estoy aprendiendo y trabajando en proyectos de <strong>Aseguramiento de Software</strong>.
        </p>
      </div>
    </section>
  );
}

export default Home;
